QWidget *VulkanPanel::createMeshControls(HexView *view){auto *container=new QWidget;container->setObjectName("meshControlsContainer");auto *layout=new QVBoxLayout(container);auto *scroll=new QScrollArea;scroll->setWidgetResizable(true);auto *controls=new Controls(this,view);scroll->setWidget(controls);layout->addWidget(scroll,1);layout->addWidget(controls->render);layout->addWidget(controls->status);auto *session=new MeshSetupSession(container);QObject::connect(view,&HexView::sourceReplaced,session,[session,r=this]{session->reset();r->scene()->clear();});return container;}
